<template><section class="catalog"><header><h2>工作事项与内容</h2><label>生效周<input type="date" v-model="effectiveWeek" :min="nextWeek"></label><button :disabled="busy" @click="load">加载该周目录</button></header><p>新版本从下周起生效。新增、删除只在保存新版本后生效，历史记录保留原事项；排列顺序决定填报页展示顺序。</p><fieldset :disabled="readOnly"><article v-for="(d,i) in entries" :key="d.id"><div class="row"><b>{{i+1}} · {{d.category||'新工作事项'}}</b><div><button :disabled="i===0" @click="move(i,-1)">上移</button><button :disabled="i===entries.length-1" @click="move(i,1)">下移</button><button :disabled="entries.length<=1" @click="remove(i)">删除</button></div></div><div class="grid"><label>工作事项<input v-model="d.category" maxlength="40"></label><label>频次<select v-model="d.frequency"><option>每日</option><option>每周</option><option>持续</option></select></label><label>填报方式<select v-model="d.reportMode"><option value="result">选择结果</option><option value="photo">只上传照片</option><option value="document">在线文档填写 / 上传工作截图</option></select></label><label v-if="d.reportMode==='result'">异常表单<select v-model="d.formType"><option value="simple">结果与验证材料</option><option value="production">异常时填写生产跟踪表</option></select></label></div><label>工作内容<textarea v-model="d.title" maxlength="300"></textarea></label><div class="row"><span>在线文档：{{d.documentTitle || (d.documentUrl ? '已绑定' : '未绑定')}}</span><button type="button" @click="emit('documents',d.id,effectiveWeek)">绑定或更换在线文档</button></div><label>输出依据<input v-model="d.evidence" maxlength="300"></label><div v-if="d.reportMode==='result'" class="grid"><label>结果选项（用顿号分隔）<input :value="d.options.join('、')" @change="d.options=split($event.target.value)"></label><label>需说明异常的选项<input :value="d.abnormalOptions.join('、')" @change="d.abnormalOptions=split($event.target.value)"></label></div><div class="row toggles"><label><input type="checkbox" v-model="d.active">启用</label><label v-if="d.reportMode==='result'"><input type="checkbox" v-model="d.abnormalEvidence">异常时必须提供照片或文档链接</label><label v-if="d.reportMode==='result'"><input type="checkbox" v-model="d.photoRequired">需要照片</label><label v-if="d.reportMode==='result' && d.photoRequired">照片要求<select v-model="d.photoWhen"><option value="always">每次填报</option><option value="abnormal">仅异常时</option></select></label><label v-for="floor in [1,2,3,4,5]" :key="floor"><input type="checkbox" :value="floor" v-model="d.floors">{{floor}} 楼</label></div></article><footer><button @click="add">＋ 新增工作事项</button><button v-if="removed.length" @click="undoRemove">撤销删除</button><button class="primary" :disabled="busy" @click="save">保存目录新版本</button></footer></fieldset><p v-if="history.length">版本记录：{{history.map(h=>`${h.effective_week}（版本${h.id}）`).join('；')}}</p></section></template>
<script setup>
import {ref,onMounted} from 'vue'
import {ElMessage} from 'element-plus'
import {work} from '../api/work'
import {addDays,weekMonday,weekCode} from '../utils/natural-week.mjs'
defineProps({readOnly:Boolean})
const emit=defineEmits(['documents'])
const today=new Date(Date.now()+8*3600000).toISOString().slice(0,10),nextWeek=addDays(weekMonday(weekCode(today)),7)
const effectiveWeek=ref(nextWeek),entries=ref([]),version=ref(0),history=ref([]),busy=ref(false),removed=ref([])
const split=text=>text.split(/[、,，]/).map(s=>s.trim()).filter(Boolean)
async function load(){busy.value=true;try{const r=await work.get('/catalog',{params:{week:effectiveWeek.value}});entries.value=r.data.entries.map(d=>({...d,active:d.active!==false,reportMode:d.reportMode||'result',photoWhen:d.photoWhen||'always',floors:d.floors||[1,2,3,4,5],formType:d.formType||(d.id==='production_progress'?'production':'simple')}));version.value=r.data.version;history.value=r.data.history;removed.value=[]}finally{busy.value=false}}
function move(i,delta){const [d]=entries.value.splice(i,1);entries.value.splice(i+delta,0,d)}
function remove(i){removed.value.push({index:i,entry:entries.value.splice(i,1)[0]})}
function undoRemove(){const last=removed.value.pop();if(last)entries.value.splice(last.index,0,last.entry)}
function add(){entries.value.push({id:'custom_'+Date.now(),category:'',title:'',evidence:'',frequency:'每日',reportMode:'result',photoWhen:'always',options:['正常','异常'],abnormalOptions:['异常'],active:true,photoRequired:false,floors:[1,2,3,4,5],formType:'simple'})}
async function save(){if(busy.value)return;busy.value=true;try{await work.post('/catalog',{effectiveWeek:effectiveWeek.value,version:version.value,entries:entries.value});ElMessage.success('目录新版本已保存');await load()}catch{}finally{busy.value=false}}
onMounted(()=>load().catch(()=>{}))
</script>
<style scoped>.catalog{display:grid;gap:16px}.catalog header,.catalog footer,.row{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}.catalog article{background:white;border:1px solid #e2e6ed;border-radius:12px;padding:18px;display:grid;gap:14px}.catalog h2{font-size:18px}.catalog label{display:grid;gap:6px}.catalog input,.catalog select,.catalog textarea{font:inherit;padding:10px;border:1px solid #cbd3df;border-radius:7px;box-sizing:border-box;width:100%}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.catalog button{min-height:44px;padding:8px 14px;border:1px solid #dce2ea;border-radius:7px;background:white;cursor:pointer}.catalog .primary{background:#bd2035;color:white}.toggles{justify-content:start}.toggles label{display:flex;align-items:center}.toggles input{width:20px;height:20px}.catalog p{font-size:14px;color:#68768a}@media(max-width:700px){.grid{grid-template-columns:1fr}}</style>

<style scoped>fieldset{border:0;padding:0;min-width:0}fieldset:disabled{opacity:.75}</style>
